INSERT INTO `chat_history` (`Chat_ID`, `User_ID`, `SessionID`, `Role`, `Message`, `Image`, `CreatedAt`) VALUES
(527, 0, 'session_692d79f099e40', 'user', 'Hãy phân tích hình ảnh này cho tôi', 'data:image/jpeg;base64,', '2025-12-01 06:20:16');
INSERT INTO `chat_history` (`Chat_ID`, `User_ID`, `SessionID`, `Role`, `Message`, `Image`, `CreatedAt`) VALUES
(528, 0, 'session_692d79f099e40', 'assistant', 'Dựa vào hình ảnh, có thể thấy chú chó này có dấu hiệu viêm da quanh vùng mắt. Vùng da này có thể bị đỏ, mất lông và có vẻ bị kích ứng.\n\nKhuyến nghị:\n\n1. **Kiểm tra thú y**: Đưa chó đến bác sĩ thú y để được kiểm tra chính xác nguyên nhân và điều trị kịp thời.\n2. **Tránh cho chó cào cấu**: Để tránh làm tình trạng nặng hơn, có thể cần dùng vòng cổ bảo vệ.\n3. **Theo dõi dị ứng hoặc nhiễm trùng**: Đây có thể là dấu hiệu của dị ứng hoặc nhiễm trùng, nên cần được điều trị phù hợp.\n\nHãy đảm bảo chú chó được chăm sóc kỹ lưỡng và theo dõi tình trạng sức khỏe thường xuyên.', NULL, '2025-12-01 06:20:24'),
(530, 4, 'chat_692dacea32e152.89059252', 'user', 'Chó nhà tôi bị ghẻ ngứa, tôi phải làm sao', NULL, '2025-12-01 09:57:46'),
(531, 4, 'chat_692dacea32e152.89059252', 'assistant', 'Nếu chó của bạn bị ghẻ ngứa, bạn nên làm những điều sau:\n\n1. **Kiểm tra và xác định**: Quan sát kỹ xem có dấu hiệu nào khác như đỏ, sưng hay rụng lông không.\n\n2. **Tắm sạch**: Tắm cho chó bằng dầu tắm chuyên dụng để làm sạch da và giảm ngứa.\n\n3. **Liên hệ bác sĩ thú y**: Đưa chó đến bác sĩ thú y để được chẩn đoán chính xác và kê thuốc điều trị phù hợp.\n\n4. **Giữ vệ sinh**: Dọn dẹp nơi ở của chó và tránh để chó tiếp xúc với các vật dụng bị nhiễm khuẩn.\n\n5. **Theo dõi tình trạng**: Quan sát sự tiến triển sau khi điều trị và tuân thủ hướng dẫn của bác sĩ.\n\nChúc chó bạn mau khỏe!', NULL, '2025-12-01 09:57:52'),
(532, 4, 'chat_692dacea32e152.89059252', 'user', 'cho tôi xin địa chỉ bên bạn, nhà tôi ở bình chánh', NULL, '2025-12-01 09:58:17'),
(533, 4, 'chat_692dacea32e152.89059252', 'assistant', 'Đây là các địa chỉ liên hệ của chúng tôi:\r\n📧 Email: haihoanpetcare@gmail.com\r\n📞 Hotline: 6969-696-###\r\n📍 TP.HCM, Việt Nam\r\n', NULL, '2025-12-01 09:58:17'),
(534, 4, 'chat_692dacea32e152.89059252', 'user', 'chó Bull của tôi bị ngứa lưng thì nên làm gì?', NULL, '2025-12-01 10:00:12'),
(535, 4, 'chat_692dacea32e152.89059252', 'assistant', 'Theo dữ liệu ghi nhận từ HaiHoanPetCare, thú cưng của bạn thuộc loài Chó và giống Bull.\r\nTriệu chứng được tìm thấy trùng khớp: Ngứa lưng.\r\nChẩn đoán gợi ý bên chúng tôi: ngứa.\r\nCách điều trị phù hợp bên chúng tôi: Gãi.\r\nNếu như tình trạng kéo dài hoặc trở nên nghiêm trọng hơn, bạn nên đưa thú cưng đến bác sĩ thú y để được thăm khám và chăm sóc kịp thời.', NULL, '2025-12-01 10:00:13'),
(536, 4, 'chat_692dacea32e152.89059252', 'user', 'bạn cho mình biết đây là bệnh gì vậy', NULL, '2025-12-01 10:02:08');
INSERT INTO `chat_history` (`Chat_ID`, `User_ID`, `SessionID`, `Role`, `Message`, `Image`, `CreatedAt`) VALUES
(537, 0, 'session_692dadf12d5d9', 'user', 'bạn cho mình biết đây là bệnh gì vậy', 'data:image/jpeg;base64,', '2025-12-01 10:02:09');
INSERT INTO `chat_history` (`Chat_ID`, `User_ID`, `SessionID`, `Role`, `Message`, `Image`, `CreatedAt`) VALUES
(538, 0, 'session_692dadf12d5d9', 'assistant', 'Dựa trên hình ảnh, chú chó có thể đang gặp vấn đề về da như viêm da, nhiễm trùng, hoặc do ký sinh trùng (như bọ chét hoặc ghẻ). Các triệu chứng như mẩn đỏ, rụng lông hoặc ngứa là dấu hiệu phổ biến của những tình trạng này.\n\nTuy nhiên, để chẩn đoán chính xác, bạn nên đưa thú cưng đến bác sĩ thú y để kiểm tra và điều trị kịp thời.', NULL, '2025-12-01 10:02:15'),
(539, 4, 'chat_692dacea32e152.89059252', 'assistant', 'Dựa trên hình ảnh, chú chó có thể đang gặp vấn đề về da như viêm da, nhiễm trùng, hoặc do ký sinh trùng (như bọ chét hoặc ghẻ). Các triệu chứng như mẩn đỏ, rụng lông hoặc ngứa là dấu hiệu phổ biến của những tình trạng này.\n\nTuy nhiên, để chẩn đoán chính xác, bạn nên đưa thú cưng đến bác sĩ thú y để kiểm tra và điều trị kịp thời.', NULL, '2025-12-01 10:02:15');

