) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Đang đổ dữ liệu cho bảng `news`
--

INSERT INTO `news` (`News_ID`, `Title`, `Summary`, `Content`, `Author`, `NewsPicture`, `Category`, `Views`, `Status`, `CreatedAt`, `UpdatedAt`) VALUES
(1, 'Cách chăm sóc thú cưng trong mùa hè', 'Những lưu ý quan trọng để giữ cho thú cưng của bạn khỏe mạnh và thoải mái trong những ngày nắng nóng.', '<h2>Giữ cho thú cưng luôn mát mẻ</h2><p>Mùa hè có thể rất khó khăn đối với thú cưng của bạn. Dưới đây là một số mẹo quan trọng:</p><ul><li>Luôn đảm bảo có nước sạch, mát</li><li>Tránh đi dạo vào giữa trưa</li><li>Cung cấp bóng mát và thông gió tốt</li><li>Không bao giờ để thú cưng trong xe</li><li>Cắt tỉa lông để giảm nhiệt</li></ul><p>Hãy chú ý đến các dấu hiệu say nắng như thở hổn hển quá mức, chảy nước dãi nhiều, hoặc lờ đờ.</p>', 'Nguyễn Văn A', 'data:image/webp;base64,', 'Sức khỏe', 1258, 'published', '2025-11-12 20:18:21', '2025-11-26 21:20:30');
INSERT INTO `news` (`News_ID`, `Title`, `Summary`, `Content`, `Author`, `NewsPicture`, `Category`, `Views`, `Status`, `CreatedAt`, `UpdatedAt`) VALUES
(2, '10 loại thức ăn tốt nhất cho chó cưng', 'Khám phá những loại thức ăn bổ dưỡng và an toàn giúp chó của bạn phát triển khỏe mạnh.', '<h2>Dinh dưỡng cho chó yêu</h2><p>Chế độ ăn cân bằng là chìa khóa cho sức khỏe của chó. Dưới đây là 10 loại thức ăn tuyệt vời:</p><ol><li><strong>Thịt gà:</strong> Giàu protein, dễ tiêu hóa</li><li><strong>Cá hồi:</strong> Chứa Omega-3 tốt cho lông và da</li><li><strong>Khoai lang:</strong> Nguồn chất xơ và vitamin A</li><li><strong>Trứng:</strong> Protein hoàn chỉnh</li><li><strong>Bí ngô:</strong> Tốt cho tiêu hóa</li><li><strong>Cà rót:</strong> Vitamin và chất xơ</li><li><strong>Táo:</strong> Vitamin C và chất xơ (bỏ hạt)</li><li><strong>Sữa chua không đường:</strong> Probiotic tốt</li><li><strong>Thịt bò nạc:</strong> Protein và sắt</li><li><strong>Rau xanh:</strong> Vitamin và khoáng chất</li></ol><p>Lưu ý: Tránh chocolate, nho, hành tây và xylitol - những thứ độc hại cho chó!</p>', 'Trần Thị B', 'data:image/jpeg;base64,', 'Dinh dưỡng', 2349, 'published', '2025-11-12 20:18:21', '2025-11-26 21:10:45');
INSERT INTO `news` (`News_ID`, `Title`, `Summary`, `Content`, `Author`, `NewsPicture`, `Category`, `Views`, `Status`, `CreatedAt`, `UpdatedAt`) VALUES
(3, 'Hướng dẫn huấn luyện mèo đi vệ sinh đúng chỗ', 'Phương pháp hiệu quả giúp mèo của bạn học cách sử dụng khay vệ sinh một cách nhanh chóng.', '<h2>Huấn luyện mèo đi vệ sinh</h2><p>Hầu hết mèo có bản năng tự nhiên sử dụng khay vệ sinh, nhưng đôi khi cần hướng dẫn:</p><h3>Bước 1: Chọn khay vệ sinh phù hợp</h3><p>Khay phải đủ lớn để mèo có thể quay người. Nếu có nhiều mèo, cần có nhiều khay (số mèo + 1).</p><h3>Bước 2: Đặt vị trí hợp lý</h3><p>Chọn nơi yên tĩnh, dễ tiếp cận nhưng riêng tư. Tránh đặt gần chỗ ăn.</p><h3>Bước 3: Giới thiệu khay</h3><p>Đặt mèo vào khay sau khi ăn hoặc ngủ dậy. Khen ngợi khi mèo sử dụng đúng.</p><h3>Bước 4: Giữ sạch sẽ</h3><p>Dọn phân hàng ngày và thay cát hoàn toàn mỗi tuần.</p><p>Nếu mèo đi vệ sinh sai chỗ, đừng phạt. Thay vào đó, tìm nguyên nhân và điều chỉnh.</p>', 'Lê Văn C', 'data:image/png;base64,', 'Huấn luyện', 904, 'published', '2025-11-12 20:18:21', '2025-12-01 06:40:56');
INSERT INTO `news` (`News_ID`, `Title`, `Summary`, `Content`, `Author`, `NewsPicture`, `Category`, `Views`, `Status`, `CreatedAt`, `UpdatedAt`) VALUES
(4, 'Những giống chó phổ biến nhất tại Việt Nam 2025', 'Tổng quan về các giống chó được yêu thích và nuôi nhiều nhất tại Việt Nam hiện nay.', '<h2>Top giống chó yêu thích 2025</h2><p>Thị trường thú cưng Việt Nam đang phát triển mạnh mẽ. Dưới đây là những giống chó hot nhất:</p><h3>1. Poodle (Chó Pú)</h3><p>Thông minh, dễ huấn luyện, không rụng lông nhiều. Có nhiều kích cỡ phù hợp với mọi gia đình.</p><h3>2. Golden Retriever</h3><p>Trung thành, thân thiện, tuyệt vời với trẻ em. Cần không gian rộng và vận động nhiều.</p><h3>3. Corgi</h3><p>Đáng yêu với đôi chân ngắn, thông minh và vui vẻ. Giá cao nhưng rất được ưa chuộng.</p><h3>4. Shiba Inu</h3><p>Độc lập, trung thành, ngoại hình đẹp. Cần người chủ kiên nhẫn trong huấn luyện.</p><h3>5. Chihuahua</h3><p>Nhỏ gọn, phù hợp chung cư. Dũng cảm và trung thành với chủ.</p><p>Hãy nghiên cứu kỹ trước khi quyết định nuôi để đảm bảo phù hợp với điều kiện sống của bạn!</p>', 'Phạm Thị D', NULL, 'Giống loài', 3167, 'published', '2025-11-12 20:18:21', '2025-12-01 14:44:23'),
(5, 'Chuẩn bị đón thú cưng mới về nhà', 'Checklist đầy đủ những gì bạn cần chuẩn bị trước khi đón một thành viên mới vào gia đình.', '<h2>Chuẩn bị đón boss mới</h2><p>Đón thú cưng mới là một quyết định lớn. Dưới đây là checklist cần thiết:</p><h3>Đồ dùng cơ bản</h3><ul><li>Bát ăn và bát nước (inox hoặc gốm)</li><li>Thức ăn phù hợp với độ tuổi</li><li>Giường hoặc nệm ngủ</li><li>Đồ chơi an toàn</li><li>Vòng cổ và dây dắt (chó)</li><li>Khay vệ sinh và cát (mèo)</li></ul><h3>Y tế</h3><ul><li>Tìm bác sĩ thú y gần nhà</li><li>Lên lịch tiêm phòng</li><li>Thuốc tẩy giun</li><li>Thuốc trị bọ chét, ve</li></ul><h3>An toàn nhà cửa</h3><ul><li>Cất giấu dây điện</li><li>Bảo vệ các vật dễ vỡ</li><li>Loại bỏ cây độc hại</li><li>Đóng cửa ban công</li></ul><h3>Thời gian</h3><p>Chuẩn bị thời gian chăm sóc, đặc biệt trong tuần đầu để thú cưng làm quen môi trường mới.</p><p>Hãy kiên nhẫn - thú cưng cần thời gian để thích nghi!</p>', 'Nguyễn Văn A', NULL, 'Tư vấn', 45, 'draft', '2025-11-12 20:18:21', '2025-11-12 20:18:21');

