DROP TABLE IF EXISTS `view_pet_detail`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_pet_detail`  AS SELECT `pet`.`Pet_ID` AS `Pet_ID`, `pet`.`PetName` AS `PetName`, `pet`.`Species` AS `Species`, `pet`.`Breed` AS `Breed`, `pet`.`Gender` AS `Gender`, `pet`.`Birthday` AS `Birthday`, `pet`.`PetPicture` AS `PetPicture`, `pet`.`User_ID` AS `User_ID`, `u`.`Fullname` AS `OwnerName`, `u`.`Email` AS `OwnerEmail`, `u`.`Phone` AS `OwnerPhone`, `pet`.`CreatedAt` AS `CreatedAt` FROM (`pet` join `user` `u` on(`pet`.`User_ID` = `u`.`User_ID`)) ;

