--
-- Cấu trúc cho view `view_wishlist_detail`
--
DROP TABLE IF EXISTS `view_wishlist_detail`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_wishlist_detail`  AS SELECT `w`.`Wishlist_ID` AS `Wishlist_ID`, `w`.`User_ID` AS `User_ID`, `u`.`Fullname` AS `UserName`, `u`.`Email` AS `UserEmail`, `w`.`Product_ID` AS `Product_ID`, `p`.`ProductName` AS `ProductName`, `p`.`Price` AS `Price`, `p`.`ProductPicture` AS `ProductPicture`, `p`.`Category` AS `Category`, `w`.`Quantity` AS `Quantity`, `p`.`Price`* `w`.`Quantity` AS `TotalPrice`, `w`.`CreatedAt` AS `CreatedAt` FROM ((`wishlist` `w` join `user` `u` on(`w`.`User_ID` = `u`.`User_ID`)) join `product` `p` on(`w`.`Product_ID` = `p`.`Product_ID`)) ;

